const $=s=>document.querySelector(s),daily=document.body.dataset.mode==='daily';
let library,byId,songs=[],game,room,busy=false,selected=null,matches=[],focus=-1,socket,reconnects=0,reconnectTimer,loading=true,serverOffset=0,lastDeadlineSync;
function notice(el,text,kind='info'){if(!el)return;el.textContent=text;el.hidden=!text;el.classList.toggle('error',kind==='error');el.setAttribute('role',kind==='error'?'alert':'status');}
function message(text,kind='info',target){if(target){notice($('#feedback-message'),'');notice($('#online-status'),'');notice($('#'+target),text?((target==='create-error'?'创建失败：':target==='join-error'?'加入失败：':'')+text):'',kind);}else if($('#online-status')){notice($('#feedback-message'),'');notice($('#online-status'),text,kind);}else notice($('#feedback-message'),text,kind);}
async function api(path,data){const response=await fetch(path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},...(data===undefined?{}:{body:JSON.stringify(data)}),signal:AbortSignal.timeout(15000)});const value=await response.json();if(!response.ok)throw Object.assign(Error(value.error||'暂时无法读取，请重试'),{status:response.status});return value;}
const roomPath=action=>'/api/rooms/'+room.code+'/'+action;
const charts=()=>daily?['billboard','weekly']:visibleCharts(room?.settings.filters);
const remaining=()=>Math.max(0,(room?.timer?.deadlineAt||0)-(Date.now()+serverOffset));
const canSearch=()=>!busy&&!loading&&game?.status==='playing'&&(daily||room?.stage==='playing');
const canGuess=()=>canSearch()&&(daily||remaining()>0&&(room.settings.mode==='classic'||room.turn===room.me));
function clearSearch(){selected=null;$('#song-search').value='';$('#clear-search').hidden=true;$('#selected-song').hidden=true;hideSuggestions();}
function hideSuggestions(){matches=[];focus=-1;$('#suggestions').hidden=true;$('#song-search').setAttribute('aria-expanded','false');$('#song-search').removeAttribute('aria-activedescendant');}
function select(id){if(!canSearch())return;const song=byId.get(id);if(!song)return;selected=id;$('#song-search').value=song.title;$('#clear-search').hidden=false;$('#selected-song').hidden=false;$('#selected-song').innerHTML=coverMarkup(song,{variant:'selected',lazy:false})+'<span class="selected-song-copy"><span class="selected-song-label">待确认的歌曲</span><strong>'+esc(song.title)+'</strong><small>'+esc(peopleText(song))+'</small></span>';hideSuggestions();}
function suggestions(){if(!canSearch())return;selected=null;$('#selected-song').hidden=true;matches=searchSongMatches(songs,$('#song-search').value,game.rows.filter(r=>r.song).map(r=>r.song.id)).slice(0,12);focus=-1;$('#suggestions').innerHTML=matches.length?matches.map(({song,matchedAlias,matchKind},i)=>'<div role="option" aria-selected="false" class="suggestion" id="song-option-'+i+'" data-id="'+esc(song.id)+'">'+coverMarkup(song,{lazy:false})+'<span class="suggestion-copy"><span class="suggestion-title">'+esc(song.title)+'</span>'+(matchedAlias&&normalize(matchedAlias)!==normalize(song.title)?'<span class="suggestion-alias">'+(matchKind==='producer'?'匹配作者：':matchKind==='singer'?'匹配歌姬：':'匹配别名：')+esc(matchedAlias)+'</span>':'')+'<span class="suggestion-sub">'+personTags(producersOf(song))+' · '+personTags(vocalistsOf(song))+'</span></span><span class="suggestion-year">'+song.year+'</span></div>').join(''):'<div class="no-suggestions">当前曲库没有找到歌曲，试试译名、罗马音或 P 主。</div>';$('#suggestions').hidden=false;$('#song-search').setAttribute('aria-expanded','true');}
function renderHints(){const h=game?.hints;if(!h)return;$('#hint-count').textContent=h.characterCount+' 字';$('#hint-sequence').setAttribute('aria-label','标题提示：'+h.maskedTitle);$('#hint-sequence').innerHTML=h.tokens.map(t=>'<span aria-hidden="true" class="'+(t.kind==='space'?'hint-space':'hint-glyph '+t.kind+(t.revealed?' revealed':''))+'">'+esc(t.text)+'</span>').join('');$('#hint-status').textContent=game.answer?'曲名已揭晓':h.revealedCount?'已揭示 '+h.revealedCount+' 字':'空格不计数';$('#hint-producer').hidden=!h.producers;$('#hint-producer').innerHTML=h.producers?'<span>这首歌的 P 主</span>'+personTags(h.producers):'';$('#hint-stages').innerHTML=[[3,'揭示 1 字'],[6,'再揭示 3 字'],[9,'揭示 P 主']].map(([n,label])=>'<span class="'+(game.rows.length>=n?'unlocked':'')+'"><b>'+n+'</b> 次 · '+label+'</span>').join('');}
function render(){
 if(!game){$('#song-search').disabled=true;$('#guess-submit').disabled=true;return;}
 const n=game.rows.length,c=charts();$('#game-heading').textContent=daily?'每日挑战':room.settings.mode==='classic'?'经典对决':'合作接力';$('#game-date').textContent=daily?game.date.replaceAll('-',' / '):'第 '+room.roundNumber+' 轮';$('#attempt-count').innerHTML=n+' <span>/ 10</span>';$('#attempt-track').innerHTML=Array.from({length:10},(_,i)=>'<i class="'+(i<n?'used ':'')+(game.status==='won'&&i<n?'won':'')+'"></i>').join('');renderHints();
 $('#clue-header').innerHTML=headerMarkup(c);$('#clue-columns').innerHTML='<col class="song-col"><col><col><col class="year-col"><col><col>'+c.map(()=>'<col><col>').join('');$('#clue-table').classList.toggle('one-chart',c.length===1);$('#guess-rows').innerHTML=game.rows.map((r,i)=>rowMarkup(r,i,c,room?.players)).join('');$('#empty-board').hidden=n>0;$('#starter-chips').innerHTML=songs.slice(0,3).map(s=>'<button class="starter-chip" type="button" data-id="'+esc(s.id)+'">'+esc(s.title)+'</button>').join('');
 $('#song-search').disabled=!canSearch();$('#guess-submit').disabled=!canGuess();$('#guess-submit').textContent=busy?'提交中…':!daily&&room.stage==='playing'&&room.settings.mode==='relay'&&room.turn!==room.me?'等待你的回合':'猜这首';$('#input-help').textContent=!daily&&room.stage==='playing'&&room.settings.mode==='relay'&&room.turn!==room.me?'你可以先搜索、选好歌曲，轮到你时再提交。':'支持译名、罗马音、P 主别名和歌姬中文名。';$('#active-filter-summary').textContent=daily?'传说曲 · 固定曲库 · '+songs.length+' 首':filterDescription(room.settings.filters)+(room.settings.filters.difficulty&&room.settings.filters.difficulty!=='custom'?'':' · '+songs.length+' 首');
 const panel=$('#result-panel');panel.hidden=!game.answer;
 panel.innerHTML=game.answer?'<h3>'+(game.status==='won'?'猜中了！':'答案揭晓')+'</h3>'+resultMarkup(game.answer)+resultDetails()+'<div class="result-actions"><button id="copy-result" class="secondary-button">复制战绩</button>'+(daily?'<a class="primary-button" href="/single">进入单人模式</a>':'')+'</div>':'';
 $('#local-note').textContent=daily?'进度由服务器保存，刷新可继续':'断线可用同一浏览器重新加入房间';$('#new-practice').hidden=true;$('#retry-views').hidden=true;$('#board-note').textContent=$('.table-scroll').scrollWidth>$('.table-scroll').clientWidth?'左右滑动查看全部线索':'';
 $('#playback-note').textContent='本局使用固定的每周播放量快照。暂无官方原投稿的数据不参与判定。';$('#snapshot-note').textContent='本局快照：'+new Date(game.revision).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});setSettingsBusy(busy);
 if(daily){$('#publish-score').hidden=game.status!=='won';$('#score-submit').disabled=busy||game.published;$('#player-nickname').disabled=Boolean(game.published);$('#score-submit').textContent=game.published?'✓ 已登记':'登记排行榜';$('#publish-score').classList.toggle('published',Boolean(game.published));$('#score-prompt').textContent=game.published?'已登记今日成绩：'+n+' 次猜中。':'你用 '+n+' 次猜中了！填写昵称，登记今日排行榜。';$('#ranking-invite').textContent=game.published?'你的成绩已登记，邀请朋友挑战吧。':game.status==='won'?'你已猜中！请在上方填写昵称，登记排行榜。':'猜中今天的歌曲后，记得登记你的成绩！';}
 if(!daily){$('#give-up').hidden=room.settings.mode!=='classic'||room.stage!=='playing'||game.status!=='playing';$('#give-up').disabled=busy;$('#end-relay').hidden=room.settings.mode!=='relay'||room.stage!=='playing'||room.host!==room.me;}
}
function resultDetails(){const song=game.answer;return '<details class="result-details"><summary>播放量与榜单记录</summary><p class="result-data">'+['niconico','youtube'].map(key=>{const v=game.answerViews[key];return key+'：'+(Number.isFinite(v?.count)?v.count.toLocaleString('zh-CN')+' 次':'暂无数据');}).join('<br>')+'<br>'+charts().map(key=>{const r=song.rankings[key];return(key==='billboard'?'周榜':'周刊总榜')+'：'+(r.status==='complete'?r.weeks+' 周 / '+(r.peak===null?'未上榜':'最高第 '+r.peak+' 名'):'暂无可核实记录');}).join('<br>')+'</p></details>';}
function renderCredits(){const b=library.charts.billboard,w=library.charts.weekly;$('#chart-sources').innerHTML='<p>Billboard 主榜：'+esc(b.from)+' — '+esc(b.through)+'，'+b.periods+' 期。</p><p>周刊总榜：#'+w.fromEpisode+' — #'+w.throughEpisode+'。</p>';$('#credits-list').innerHTML=songs.slice(0,100).map(s=>'<div class="credit-row"><span>'+esc(s.title)+'<small>'+personTags(producersOf(s))+' · '+personTags(vocalistsOf(s))+' · '+s.year+'</small></span></div>').join('')+(songs.length>100?'<p class="dialog-note">此处列出当前曲库前 100 首，共 '+songs.length+' 首；全部歌曲均可在搜索中查询。</p>':'');}
function acceptDaily(value){const won=game&&game.status!=='won'&&value.status==='won';game=value;songs=value.poolIds.map(id=>byId.get(id)).filter(Boolean);for(const row of value.rows)byId.set(row.song.id,row.song);loading=false;render();if(won){celebrate('daily|'+game.date,'猜中了！记得登记排行榜');$('#publish-score').scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}}
function acceptRoom(value){if(room&&value.code===room.code&&value.version<room.version)return;const changed=room?.code!==value.code||room?.roundNumber!==value.roundNumber,won=room&&room.roundNumber===value.roundNumber&&game?.status!=='won'&&value.game?.status==='won';room=value;serverOffset=(value.timer?.serverNow||Date.now())-Date.now();setRoomSettingsContext(room.settings.filters,room.host!==room.me||room.stage!=='lobby');game=room.game;if(changed)clearSearch();songs=(value.poolIds||[]).map(id=>byId.get(id)).filter(Boolean);for(const row of game?.rows||[])if(row.song)byId.set(row.song.id,row.song);if(selected&&game?.rows.some(r=>r.song?.id===selected))clearSearch();loading=false;$('#room-entry').hidden=true;$('#room-panel').hidden=false;$('#game-panel').hidden=!game;try{localStorage.setItem('chu-yiba:room',room.code);}catch{}renderRoom();render();if(won){const actor=room.players.find(p=>p.id===room.result?.winner)?.nickname;celebrate('room|'+room.code+'|'+room.roundNumber+'|'+room.me,room.settings.mode==='relay'?(actor||'队友')+' 猜中了！+1 分':'猜中了！');}}
async function dailySync(){acceptDaily(await api('/api/daily'));}
function exitRoom(reason){const old=socket;socket=null;clearTimeout(reconnectTimer);old?.close();room=null;game=null;setRoomSettingsContext(null);try{localStorage.removeItem('chu-yiba:room');}catch{}$('#room-panel').hidden=true;$('#game-panel').hidden=true;$('#room-clock').hidden=true;$('#room-entry').hidden=false;clearSearch();if(reason)message(reason,'error');}
async function roomSync(){try{acceptRoom(await api(roomPath('state')));}catch(error){if(error.status===404)exitRoom(error.message);throw error;}}
async function run(action,target){if(busy)return;message('', 'info',target);if(target){notice($('#create-error'),'');notice($('#join-error'),'');}busy=true;setSettingsBusy(true);render();if($('#create-room')){$('#create-room').disabled=true;$('#join-room').disabled=true;}try{await action();}catch(error){message(error.name==='TimeoutError'?'网络超时，请重试。':error.message,'error',target);if(error.status===404&&room)exitRoom(error.message);if(error.status===409||error.name==='TimeoutError'){try{if(daily)await dailySync();else if(room)await roomSync();}catch{}}}finally{busy=false;setSettingsBusy(false);render();if(room)renderRoom();if($('#create-room')){$('#create-room').disabled=false;$('#join-room').disabled=false;}}}
async function submit(id){if(!canGuess())throw Error(!daily&&room?.settings.mode==='relay'&&room.turn!==room.me?'还没轮到你，可以先搜索歌曲。':'当前不能提交，请等待同步。');if(typeof id!=='string')throw Error('请先选择歌曲');await run(async()=>{const payload=daily?{songId:id,version:game.version}:{songId:id,round:room.roundNumber,attempts:game.rows.length};const value=await api(daily?'/api/daily/guess':roomPath('guess'),payload);daily?acceptDaily(value):acceptRoom(value);clearSearch();message(game.status==='won'?'猜中了！':game.status==='lost'?'本轮已经结束。':'线索已更新。');});return daily?game:room;}
async function rankings(){try{const value=await api('/api/leaderboard');$('#ranking-date').textContent=value.date;$('#ranking-list').innerHTML=value.entries.length?value.entries.map(e=>'<li><span class="ranking-place">'+e.rank+'</span><strong>'+esc(e.nickname)+'</strong><span>'+e.attempts+' 次</span></li>').join(''):'<li class="ranking-empty">今天还没有成绩，来成为第一位吧。</li>';}catch(error){$('#ranking-list').innerHTML='<li class="ranking-empty">'+esc(error.message)+'</li>';}}
async function roomAction(action,input={}){acceptRoom(await api(roomPath(action),input));}
function connect(){
 if(!room)return;clearTimeout(reconnectTimer);const code=room.code;socket?.close();socket=new WebSocket(location.origin.replace(/^http/,'ws')+'/api/rooms/'+code+'/events');const current=socket;
 current.onopen=()=>{if(current!==socket)return;reconnects=0;$('#connection-status').textContent='已连接';};
 current.onmessage=event=>{if(current!==socket)return;try{const data=JSON.parse(event.data);if(data.type==='state')acceptRoom(data.state);else if(data.type==='closed')exitRoom(data.reason);}catch{}};
 current.onclose=()=>{if(current!==socket||room?.code!==code)return;$('#connection-status').textContent='连接中断，可重新连接';if(reconnects<5)reconnectTimer=setTimeout(async()=>{reconnects++;try{await roomSync();}catch{if(!room)return;}if(room?.code===code)connect();},Math.min(30000,1000*2**reconnects));};
}
function renderRoom(){
 const host=room.host===room.me,lobby=room.stage==='lobby',me=room.players.find(p=>p.id===room.me);$('#room-code').textContent=room.code;$('#member-count').textContent=room.players.length+' / '+room.settings.capacity;$('#room-setting-label').textContent=room.settingLabel+' · '+(room.settings.mode==='classic'?'经典对决 · 每轮 3 分钟':'合作接力 · 每人 1 分钟')+' · BO'+room.settings.bo;
 $('#room-players').innerHTML=(room.stage==='finished'?[...room.players].sort((a,b)=>b.score-a.score):room.players).map(p=>{const turn=room.turn===p.id,status=lobby?p.ready?'✓ 已准备':'等待准备':turn?'正在猜歌':p.finished?'本轮已结束':p.connected?'在线':'暂时断线';return '<li class="'+(turn?'is-turn ':'')+(p.id===room.me?'is-me':'')+'"><span class="player-identity"><strong>'+esc(p.nickname)+'</strong><span class="player-badges">'+(p.id===room.host?'<small>房主</small>':'')+(p.id===room.me?'<small>你</small>':'')+'</span></span><span class="player-state '+(turn?'active':lobby&&p.ready?'ready':'')+'">'+status+(p.attempts!==undefined?'<small>'+(p.won?p.attempts+' 次猜中':p.timedOut?'超时未猜中':'未猜中')+'</small>':'')+'</span><span class="player-score"><b>'+p.score+'</b><small>分</small></span></li>';}).join('');
 $('#room-host-settings').hidden=!(host&&lobby);$('#host-mode').value=room.settings.mode;$('#host-bo').value=room.settings.bo;$('#host-capacity').value=room.settings.capacity;$('#host-capacity').disabled=room.settings.mode==='classic';$('#ready-room').hidden=!lobby;$('#ready-room').textContent=me.ready?'✓ 已准备 · 取消':'点击准备';$('#ready-room').classList.toggle('ready-complete',me.ready);$('#start-room').hidden=!(host&&lobby);$('#start-room').disabled=busy||room.players.length<2||room.players.some(p=>!p.ready);$('#next-round').hidden=!(host&&room.stage==='between');$('#rematch-room').hidden=!(host&&['finished','cancelled'].includes(room.stage));$('#leave-room').hidden=['playing','between'].includes(room.stage);$('#close-match').hidden=!(host&&['playing','between'].includes(room.stage));
 const turn=room.players.find(p=>p.id===room.turn)?.nickname,winner=room.players.find(p=>p.id===room.result?.winner)?.nickname;
 const waiting=room.players.filter(p=>!p.ready).length;
 $('#room-progress').textContent=lobby?(!me.ready?'你还未准备，请点击「准备」。':'你已准备。')+(room.players.length<2?' 等待朋友加入。':waiting?' 还差 '+waiting+' 人准备。':host?' 全员已准备，可以开始！':' 全员已准备，等待房主开始。'):room.stage==='cancelled'?'对局已由房主结束。':room.stage==='finished'?'比赛结束 · '+(room.result?.reason==='timeout'?'本轮时间已到。 ':'')+[...room.players].sort((a,b)=>b.score-a.score).map(p=>p.nickname+' '+p.score+' 分').join(' / '):room.stage==='between'?(room.result?.reason==='timeout'?'时间已到。 ':'')+(winner?winner+' 赢下本轮，+1 分！':'本轮平局，双方均不加分。')+' 等待房主开始下一轮。':room.settings.mode==='relay'?(room.turn===room.me?'轮到你了，请在 1 分钟内猜测！':'轮到 '+turn+'，你可以提前搜索。'):'每轮限时 3 分钟，按猜中次数判胜。';
 $('#room-panel').querySelectorAll('button').forEach(b=>{if(b.id!=='start-room')b.disabled=busy;});
 renderClock();
}
function renderClock(){
 if(daily||!room)return;const timer=room.timer,active=room.stage==='playing',relay=room.settings.mode==='relay',turn=room.players.find(p=>p.id===room.turn)?.nickname,left=Math.ceil(remaining()/1000),clock=$('#room-clock');clock.hidden=!timer;clock.classList.toggle('is-your-turn',active&&relay&&room.turn===room.me);clock.classList.toggle('urgent',left<=30);clock.classList.toggle('waiting',!active);$('#clock-label').textContent=active?(relay?'本次猜测剩余时间':'本轮剩余时间'):'房间自动关闭倒计时';$('#turn-player').textContent=active?(relay?(room.turn===room.me?'轮到你猜歌！':'现在轮到 '+turn):'经典对决 · 第 '+room.roundNumber+' 轮'):'等待'+(room.stage==='lobby'?'开局':'开始新一轮');$('#clock-note').textContent=active?(relay?'超时提交空白答案，消耗 1 次并计入标题提示':'超时自动结算；双方未猜中则无人得分'):'等待满 10 分钟自动关闭；开始游戏后取消关闭倒计时';$('#clock-time').textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');$('#clock-time').setAttribute('aria-label','剩余 '+Math.floor(left/60)+' 分 '+left%60+' 秒');$('#guess-submit').disabled=!canGuess();
 const key=room.code+'|'+timer?.deadlineAt;
 if(left===0&&!busy&&!loading&&lastDeadlineSync!==key){lastDeadlineSync=key;void roomSync().catch(error=>{if(room)message(error.message,'error');});}
}
setInterval(renderClock,250);
function attach(){
 $('#song-search').addEventListener('input',()=>{$('#clear-search').hidden=!$('#song-search').value;suggestions();});$('#song-search').addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='Escape')hideSuggestions();if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();if($('#suggestions').hidden)suggestions();if(!matches.length)return;focus=(focus+(e.key==='ArrowDown'?1:-1)+matches.length)%matches.length;$('#suggestions').querySelectorAll('.suggestion').forEach((el,i)=>{el.classList.toggle('focused',i===focus);el.setAttribute('aria-selected',String(i===focus));});$('#song-search').setAttribute('aria-activedescendant','song-option-'+focus);}if(e.key==='Enter'&&focus>=0&&!$('#suggestions').hidden){e.preventDefault();select(matches[focus].song.id);}});$('#clear-search').addEventListener('click',clearSearch);$('#suggestions').addEventListener('click',e=>{const el=e.target.closest('[data-id]');if(el)select(el.dataset.id);});$('#starter-chips').addEventListener('click',e=>{const el=e.target.closest('[data-id]');if(el)select(el.dataset.id);});document.addEventListener('click',e=>{if(!$('#guess-form').contains(e.target))hideSuggestions();});$('#guess-form').addEventListener('submit',e=>{e.preventDefault();if(!selected){const exact=songs.filter(s=>[s.title,...s.aliases].some(t=>normalize(t)===normalize($('#song-search').value)));if(exact.length===1)selected=exact[0].id;}void submit(selected).catch(e=>message(e.message));});
 for(const [button,dialog] of [['rules-open','rules-dialog'],['credits-open','credits-dialog']])$('#'+button).addEventListener('click',()=>{if(button==='credits-open')renderCredits();$('#'+dialog).showModal();});
 $('#result-panel').addEventListener('click',async e=>{if(!e.target.closest('#copy-result'))return;const squares={exact:'🟩',close:'🟨',wrong:'⬛',unknown:'⬜'},text='初一把 · '+(daily?game.date:room.settings.mode==='classic'?'经典对决':'合作接力')+'\n'+(game.status==='won'?game.rows.length:'X')+'/10\n'+game.rows.map(r=>[r.feedback.song,r.feedback.producer,r.feedback.singers,r.feedback.year.status,...['niconico','youtube'].map(p=>r.feedback.views[p].status),...charts().flatMap(c=>[r.feedback[c].weeks.status,r.feedback[c].peak.status])].map(v=>squares[v]).join('')).join('\n');try{await navigator.clipboard.writeText(text);message('战绩已复制，不包含答案。');}catch{message('浏览器未允许复制。');}});
 if(daily){$('#refresh-rankings').addEventListener('click',rankings);$('#publish-score').addEventListener('submit',e=>{e.preventDefault();void run(async()=>{acceptDaily(await api('/api/daily/score',{nickname:$('#player-nickname').value}));try{localStorage.setItem('chu-yiba:nickname',$('#player-nickname').value);}catch{}await rankings();message('✓ 成绩已加入今日排行榜。','success','score-status');},'score-status');});setInterval(()=>{if(game?.date!==getBeijingDate()&&!busy)void run(async()=>{await dailySync();clearSearch();await rankings();message('今天的新挑战已更新。');});},60000);}
 else attachRooms();
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&!busy&&!loading)void run(async()=>{if(daily)await dailySync();else if(room){await roomSync();if(socket?.readyState!==WebSocket.OPEN)connect();}});});
}
function attachRooms(){
 const filterLabel=()=>$('#room-filter-label').textContent=filterDescription(readFilters());filterLabel();
 window.addEventListener('chu-settings-change',()=>{filterLabel();if(room&&room.host===room.me&&room.stage==='lobby')void run(()=>roomAction('configure',{...room.settings,filters:readFilters()}));});
 $('#create-mode').addEventListener('change',()=>{const classic=$('#create-mode').value==='classic';$('#create-capacity').disabled=classic;$('#create-capacity').value=classic?'2':'4';});
 $('#create-room').addEventListener('click',()=>void run(async()=>{const value=await api('/api/rooms',{nickname:$('#room-nickname').value,mode:$('#create-mode').value,bo:Number($('#create-bo').value),capacity:Number($('#create-capacity').value),filters:readFilters()});acceptRoom(value);try{localStorage.setItem('chu-yiba:nickname',$('#room-nickname').value);}catch{}connect();},'create-error'));
 $('#join-room').addEventListener('click',()=>void run(async()=>{const code=$('#join-code').value.trim().toUpperCase();if(!/^[A-HJ-NP-Z2-9]{6}$/.test(code))throw Error('请填写 6 位房间码');acceptRoom(await api('/api/rooms/'+code+'/join',{nickname:$('#room-nickname').value}));connect();},'join-error'));
 $('#ready-room').addEventListener('click',()=>void run(()=>roomAction('ready',{ready:!room.players.find(p=>p.id===room.me).ready})));
 $('#start-room').addEventListener('click',()=>void run(()=>roomAction('start')));$('#next-round').addEventListener('click',()=>void run(()=>roomAction('next',{round:room.roundNumber})));$('#rematch-room').addEventListener('click',()=>void run(()=>roomAction('rematch')));
 $('#save-room-settings').addEventListener('click',()=>void run(()=>roomAction('configure',{mode:$('#host-mode').value,bo:Number($('#host-bo').value),capacity:Number($('#host-capacity').value),filters:room.settings.filters})));
 $('#host-mode').addEventListener('change',()=>{const classic=$('#host-mode').value==='classic';$('#host-capacity').disabled=classic;if(classic)$('#host-capacity').value='2';});
 $('#reconnect-room').addEventListener('click',()=>void run(async()=>{await roomSync();connect();}));
 $('#copy-invite').addEventListener('click',async()=>{const text=location.origin+'/multi?room='+room.code;try{await navigator.clipboard.writeText(text);$('#room-progress').textContent='邀请链接已复制。';}catch{$('#room-progress').textContent='邀请链接：'+text;}});
 $('#copy-room-code').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(room.code);message('房间码已复制。');}catch{message('房间码：'+room.code);}});
 $('#give-up').addEventListener('click',()=>$('#give-up-dialog').showModal());$('#confirm-give-up').addEventListener('click',()=>{$('#give-up-dialog').close();void run(()=>roomAction('give-up',{round:room.roundNumber}));});
 $('#end-relay').addEventListener('click',()=>$('#end-round-dialog').showModal());$('#confirm-end-round').addEventListener('click',()=>{$('#end-round-dialog').close();void run(()=>roomAction('end-round',{round:room.roundNumber}));});
 $('#close-match').addEventListener('click',()=>$('#close-match-dialog').showModal());$('#confirm-close-match').addEventListener('click',()=>{$('#close-match-dialog').close();void run(()=>roomAction('close-match'));});
 $('#leave-room').addEventListener('click',()=>void run(async()=>{await api(roomPath('leave'),{});exitRoom();}));
}
async function init(){try{library=await getLibrary();byId=new Map(library.songs.map(s=>[s.id,s]));installCoverFallback(document,id=>byId.get(id));$('#library-count').textContent=library.songs.length;$('.library-footnote').textContent='每天固定传说曲；单人和房间可选择难度或自定义范围。';attach();if(daily){await dailySync();try{$('#player-nickname').value=localStorage.getItem('chu-yiba:nickname')||'';}catch{}await rankings();}else{loading=false;const requested=new URL(location.href).searchParams.get('room');let saved;try{saved=localStorage.getItem('chu-yiba:room');$('#room-nickname').value=localStorage.getItem('chu-yiba:nickname')||'';}catch{}if(requested)$('#join-code').value=requested.toUpperCase();if(saved&&(!requested||saved===requested.toUpperCase())){try{acceptRoom(await api('/api/rooms/'+saved+'/state'));connect();}catch{try{localStorage.removeItem('chu-yiba:room');}catch{}}}}}catch(error){loading=false;message(error.message+' 请刷新重试。');}}
if(document.modelContext?.registerTool){document.modelContext.registerTool({name:'get_online_game',description:'Read only the visible daily or room clues. No hidden answer is returned.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>daily?game:room});document.modelContext.registerTool({name:'search_online_songs',description:'Search the current game library without guessing.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>searchSongMatches(songs,input.query).slice(0,12).map(r=>({id:r.song.id,title:r.song.title}))});document.modelContext.registerTool({name:'guess_online_song',description:'Submit a song guess to the server and consume one attempt.',inputSchema:{type:'object',properties:{songId:{type:'string'}},required:['songId'],additionalProperties:false},execute:input=>submit(input.songId)});}
void init();
window.addEventListener('resize',()=>{if(game)$('#board-note').textContent=$('.table-scroll').scrollWidth>$('.table-scroll').clientWidth?'左右滑动查看全部线索':'';});
